#!/usr/bin/env bash
# EBCC downstream rerun for breast_cancer (../EBCC_PIPELINE.md sections 5-8):
# wait for the 02 EBCC grids -> 03 -> 04 (+ 05 per dataset as soon as its 04 is done) -> figures.
# Run it in screen so it survives a dropped connection:
#   screen -dmS bc_pipeline bash -c 'cd $PROJECT_ROOT/breast_cancer && bash run_pipeline.sh > logs/pipeline.log 2>&1'
# Options (environment): MAX_JOBS (04 jobs at a time, default 6), MAX_JOBS_05 (05 jobs at a time,
#   default 3), THREADS (per job, default 8), SKIP_WAIT=1 (don't wait for the 02 grids).
# Do not edit this file while it runs (bash reads it as it goes).
set -u
cd "$(dirname "$0")"
DATASETS="full_mouse dissected_mouse genes2 genes4 genes6 genes8"   # as in integration_sets.R / datasets.py
export MAX_JOBS=${MAX_JOBS:-6} THREADS=${THREADS:-8} DATASETS
export OPENBLAS_NUM_THREADS=$THREADS OMP_NUM_THREADS=$THREADS MKL_NUM_THREADS=$THREADS N_THREADS=$THREADS N_CPU=$THREADS
export RETICULATE_PYTHON=${CONDA_ENVS:?set CONDA_ENVS to the folder holding the conda environments}/torch/bin/python
PY_SCIB=${CONDA_ENVS:?set CONDA_ENVS to the folder holding the conda environments}/scib/bin/python
PY_TORCH=${CONDA_ENVS:?set CONDA_ENVS to the folder holding the conda environments}/torch/bin/python
mkdir -p logs/02 logs/03 logs/04 logs/05
step() { echo "== $* ($(date))"; }

# ---- 02: wait for both EBCC grids (and the mouse final fit) ----
if [ "${SKIP_WAIT:-0}" != 1 ]; then
  step "waiting for the 02 EBCC grids (logs/02/*_ebcc_grid.log)"
  for sp in human mouse; do
    until grep -qE "RUN FINISHED|Error|Execution halted" logs/02/${sp}_ebcc_grid.log 2>/dev/null; do sleep 120; done
    if ! grep -q "RUN FINISHED" logs/02/${sp}_ebcc_grid.log; then echo "STOP: the $sp EBCC grid failed, see logs/02/${sp}_ebcc_grid.log"; exit 1; fi
    step "02 $sp done: $(tail -1 data/02_annotated_data/${sp}_ebcc_heldout_grid_chosen.csv)"
  done
fi
Rscript -e "suppressMessages(source('../library.R')); for (s in c('human', 'mouse')) {
  o = readRDS(sprintf('data/02_annotated_data/02_%s_annotated.rds', s))
  if (!all(c('celltype', 'ebcc_label') %in% colnames(o@meta.data))) stop(s, ' has no EBCC labels') }; cat('02 objects ok\n')" \
  || { echo "STOP: 02 objects are not ready"; exit 1; }

# ---- 03 ----
# SKIP_03=1 uses the 03 datasets already on disk (all six must exist) and starts at the fingerprint
if [ "${SKIP_03:-0}" = 1 ]; then
  for g in $DATASETS; do [ -f data/$g/03_concatenated_data.h5ad ] || { echo "STOP: SKIP_03 but data/$g is missing"; exit 1; }; done
  step "03 skipped (SKIP_03=1)"
else
# ---- 03 ----
# PART_A=pipeline/03_partA2_dissected.R rebuilds only dissected_mouse (full_mouse already built)
PART_A=${PART_A:-pipeline/03_partA_datasets.R}
step "03 part A: $PART_A"
nice -n 10 Rscript $PART_A > logs/03/partA.log 2>&1 || { echo "STOP: 03 part A failed, see logs/03/partA.log"; exit 1; }
step "03 part B: nested gene removal, one process per level"
pids=""
for p in 0.2 0.4 0.6 0.8; do
  nice -n 10 Rscript pipeline/03_partB_reduce_genes.R $p > logs/03/partB_$p.log 2>&1 & pids="$pids $!"
done
ok=1; for pid in $pids; do wait $pid || ok=0; done
[ $ok = 1 ] || { echo "STOP: 03 part B failed, see logs/03/partB_*.log"; exit 1; }
fi
# fingerprint of each concatenated dataset (md5 of cell and gene names), for deciding later reruns
$PY_TORCH -c "
import hashlib, anndata as ad
for g in '$DATASETS'.split():
    a = ad.read_h5ad(f'data/{g}/03_concatenated_data.h5ad', backed='r')
    md5 = lambda x: hashlib.md5('\n'.join(map(str, x)).encode()).hexdigest()
    line = f'{g}\tcells={a.n_obs}\tgenes={a.n_vars}\tcells_md5={md5(a.obs_names)}\tgenes_md5={md5(a.var_names)}'
    open(f'data/{g}/03_fingerprint.txt', 'w').write(line + '\n'); print(line)
" || { echo "STOP: fingerprinting failed"; exit 1; }

# ---- 04, with 05 starting per dataset as soon as that dataset's 04 is done ----
step "04"
bash run_04.sh > logs/04/run_04.log 2>&1 & r04=$!

MAX_JOBS_05=${MAX_JOBS_05:-3}
OUTPUTS="04.01_FastMNN 04.02_SAMap 04.03_CCA 04.04_Harmony 04.05_Scanorama 04.06_RPCA 04.07_scVI
         04.08_scANVI 04.09_BBKNN 04.10_LIGER 04.11_LIGER_UINMF 04.12_FastMNN_UINMF 04.13_CCA_UINMF
         04.14_Harmony_UINMF 04.15_Scanorama_UINMF 04.16_RPCA_UINMF 04.17_BBKNN_UINMF"
# ready = eval_cells.txt and every 04 output written after this dataset's 03 data, and no 04 job still on it
ready() {
  local g=$1 o
  [ "data/$g/eval_cells.txt" -nt "data/$g/03_concatenated_data.h5ad" ] || return 1
  for o in $OUTPUTS; do [ "data/$g/$o.h5ad" -nt "data/$g/03_concatenated_data.h5ad" ] || return 1; done
  ! pgrep -u "$USER" -f "04\.[0-9]+_[A-Za-z_]+\.(R|py) $g( |$)" > /dev/null
}
score() {
  step "05 $1"
  for f in 05*.py; do echo "nice -n 10 $PY_SCIB $f $1 > logs/05/${f%.*}_$1.log 2>&1"; done \
    | xargs -P "$MAX_JOBS_05" -I{} bash -c '{} && echo "done:   {}" || echo "FAILED: {}"'
}
pending="$DATASETS"
while [ -n "$pending" ]; do
  still=""
  r04_running=$(kill -0 $r04 2>/dev/null && echo 1 || echo 0)
  for g in $pending; do
    # once 04 has finished, score whatever is left (a missing output then shows up as a 05 error)
    if ready $g || [ $r04_running = 0 ]; then score $g; else still="$still $g"; fi
  done
  pending=$(echo $still)
  [ -n "$pending" ] && sleep 120
done
wait $r04
grep -E "^FAILED" logs/04/run_04.log || echo "no failed 04 jobs"

# ---- figures (../analysis/visualisations.R, breast_cancer entry) ----
step "figures"
rm -rf ../figures/breast_cancer/umap ../figures/breast_cancer/spatial
( cd .. && nice -n 10 Rscript analysis/visualisations.R breast_cancer ) > logs/visualisations.log 2>&1 \
  && echo "figures done" || echo "FAILED: figures, see logs/visualisations.log"

step "PIPELINE FINISHED; check FAILED lines above and logs/03, logs/04, logs/05"
